'use strict';
const $=id=>document.getElementById(id), canvas=$('canvas'), ctx=canvas.getContext('2d');
const palettes={gold:['#fff1b1','#d6b768','#8a5b22','香槟金'],silver:['#f4fcff','#b8c8d7','#566b80','铂金银'],rose:['#ffe5cc','#d4a28d','#875647','玫瑰金'],violet:['#ece3ff','#a696dd','#544687','极光紫']};
const state={shape:'coin',color:'gold',depth:12,metal:80,rough:25,scale:65,angle:-.15,tilt:-.08,zoom:1,image:null};
function outline(c,r){c.beginPath();if(state.shape==='coin')c.arc(0,0,r,0,Math.PI*2);else if(state.shape==='shield'){c.moveTo(-r*.84,-r*.82);c.lineTo(r*.84,-r*.82);c.bezierCurveTo(r*.98,r*.25,r*.5,r*.75,0,r);c.bezierCurveTo(-r*.5,r*.75,-r*.98,r*.25,-r*.84,-r*.82)}else{const n=state.shape==='hex'?6:120;for(let i=0;i<=n;i++){const a=i/n*Math.PI*2-Math.PI/2,rr=state.shape==='flower'?r*(.92+.08*Math.cos(a*12)):r;const x=Math.cos(a)*rr,y=Math.sin(a)*rr;i?c.lineTo(x,y):c.moveTo(x,y)}}c.closePath()}
function render(c,w,h,exporting=false){c.clearRect(0,0,w,h);const r=Math.min(w,h)*.31*state.zoom,p=palettes[state.color],sx=Math.max(.28,Math.cos(state.angle)),sy=Math.max(.7,Math.cos(state.tilt));c.save();c.translate(w/2,h*.51);if(!exporting){c.save();c.translate(0,r*1.25);c.scale(1,.15);const g=c.createRadialGradient(0,0,0,0,0,r*1.1);g.addColorStop(0,'#45532b33');g.addColorStop(1,'#45532b00');c.fillStyle=g;c.beginPath();c.arc(0,0,r*1.1,0,7);c.fill();c.restore()}c.transform(sx,state.tilt*.15,-state.angle*.1,sy,0,0);
for(let d=state.depth;d>=0;d--){c.save();c.translate(d*Math.sin(state.angle)*1.4,d*.65);outline(c,r);const g=c.createLinearGradient(-r,-r,r,r);g.addColorStop(0,p[0]);g.addColorStop(.25,p[2]);g.addColorStop(.5,p[1]);g.addColorStop(1,p[2]);c.fillStyle=g;c.fill();c.restore()}
outline(c,r);const face=c.createLinearGradient(-r,-r,r,r);face.addColorStop(0,p[0]);face.addColorStop(.32,p[1]);face.addColorStop(.52,p[0]);face.addColorStop(.75,p[1]);face.addColorStop(1,p[2]);c.fillStyle=face;c.fill();c.save();c.clip();c.globalAlpha=(100-state.rough)/100*state.metal/100*.35;const shine=c.createLinearGradient(-r,0,r,0);shine.addColorStop(0,'#fff0');shine.addColorStop(.45,'#ffffff');shine.addColorStop(.6,'#fff0');c.fillStyle=shine;c.fillRect(-r,-r,r*2,r*2);c.restore();
for(const [factor,color,line] of [[.94,p[0],2],[.89,p[2],1],[.85,p[0],1]]){outline(c,r*factor);c.strokeStyle=color;c.lineWidth=line*w/800;c.stroke()}
c.save();outline(c,r*.82);c.clip();const size=r*2*state.scale/100;if(state.image){const im=state.image,ratio=Math.min(size/im.width,size/im.height),iw=im.width*ratio,ih=im.height*ratio;c.shadowColor=p[2];c.shadowBlur=3*w/800;c.shadowOffsetX=2*w/800;c.shadowOffsetY=3*w/800;c.drawImage(im,-iw/2,-ih/2,iw,ih)}else{c.lineCap='round';for(const [rr,color,start] of [[size*.48,'#fc3972',.7],[size*.35,'#b5fa35',1.1],[size*.22,'#5be5e8',1.4]]){c.beginPath();c.arc(0,0,rr,-Math.PI/2,-Math.PI/2+Math.PI*2-start);c.strokeStyle=p[2];c.lineWidth=size*.15;c.shadowColor=p[2];c.shadowBlur=5;c.stroke();c.shadowBlur=0;c.strokeStyle=color;c.lineWidth=size*.12;c.stroke()}}c.restore();c.restore()}
function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio,2);canvas.width=rect.width*dpr;canvas.height=rect.height*dpr}new ResizeObserver(resize).observe(canvas);
let last=0;function animate(t){const dt=Math.min(t-last,50);last=t;if($('spin').checked&&!dragging&&!matchMedia('(prefers-reduced-motion: reduce)').matches)state.angle=Math.sin(t*.0003)*.38;render(ctx,canvas.width,canvas.height);requestAnimationFrame(animate)}let dragging=false,px=0,py=0;canvas.addEventListener('pointerdown',e=>{dragging=true;px=e.clientX;py=e.clientY;canvas.setPointerCapture(e.pointerId);$('spin').checked=false});canvas.addEventListener('pointermove',e=>{if(dragging){state.angle=Math.max(-1.2,Math.min(1.2,state.angle+(e.clientX-px)*.008));state.tilt=Math.max(-.8,Math.min(.8,state.tilt+(e.clientY-py)*.008));px=e.clientX;py=e.clientY}});canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointercancel',()=>dragging=false);canvas.addEventListener('wheel',e=>{e.preventDefault();state.zoom=Math.max(.6,Math.min(1.3,state.zoom-e.deltaY*.001))},{passive:false});$('reset').onclick=()=>{state.angle=-.15;state.tilt=-.08;state.zoom=1};
for(const key of ['depth','metal','rough','scale'])$(key).oninput=e=>{state[key]=+e.target.value;$(key+'Value').value=e.target.value+(key==='depth'?'':'%')};
document.querySelectorAll('[data-shape],[data-color]').forEach(b=>b.onclick=()=>{const key=b.dataset.shape?'shape':'color';state[key]=b.dataset[key];document.querySelectorAll('[data-'+key+']').forEach(el=>el.classList.toggle('active',el===b));if(key==='color')$('material').textContent=palettes[state.color][3]});$('title').oninput=()=>$('awardTitle').textContent=$('title').value||'我的运动奖章';
let uploadSequence=0;async function upload(file){if(!file)return;const sequence=++uploadSequence;try{if(file.size>10*1024*1024)throw Error('图片超过 10 MB，请选择较小的文件');const svg=/\.svg$/i.test(file.name)||file.type==='image/svg+xml',png=/\.png$/i.test(file.name)||file.type==='image/png';if(!svg&&!png)throw Error('请选择 PNG 或 SVG 图片');let blob=file;if(svg){const text=await file.text(),doc=new DOMParser().parseFromString(text,'image/svg+xml');if(doc.querySelector('parsererror')||doc.documentElement.localName!=='svg')throw Error('SVG 文件格式不正确');if(doc.querySelector('script,foreignObject,image,use,style,animate,set')||[...doc.querySelectorAll('*')].some(el=>[...el.attributes].some(a=>/^on/i.test(a.name)||/href/i.test(a.name)||/url\s*\(/i.test(a.value))))throw Error('请使用不含脚本或外部资源的纯图形 SVG');blob=new Blob([new XMLSerializer().serializeToString(doc)],{type:'image/svg+xml'})}else{const bytes=new Uint8Array(await file.slice(0,8).arrayBuffer());if(bytes.join(',')!=='137,80,78,71,13,10,26,10')throw Error('PNG 文件格式不正确')}
const url=URL.createObjectURL(blob);try{const im=new Image();im.src=url;await im.decode();if(im.width*im.height>40000000)throw Error('图片尺寸过大，请缩小后上传');if(sequence===uploadSequence){state.image=im;$('status').textContent='已载入：'+file.name}}finally{URL.revokeObjectURL(url)}}catch(e){if(sequence===uploadSequence)$('status').textContent=e.message}}
$('file').onchange=e=>upload(e.target.files[0]);$('demo').onclick=()=>{uploadSequence++;state.image=null;$('file').value='';$('status').textContent='已使用活动圆环示例'};const drop=$('drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');upload(e.dataTransfer.files[0])};
$('download').onclick=()=>{const out=document.createElement('canvas');out.width=out.height=2048;const prev=state.zoom;state.zoom=1;render(out.getContext('2d'),2048,2048,true);state.zoom=prev;out.toBlob(blob=>{if(!blob){$('status').textContent='导出失败，请重试';return}const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=($('title').value||'medal')+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},'image/png')};requestAnimationFrame(animate);
